"use strict";

const http = require("http");
const https = require("https");
const zlib = require("zlib");
const { URL } = require("url");

const UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36";

const NAV_HEADERS = {
  "user-agent": UA,
  accept:
    "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
  "accept-language": "ja-JP,ja;q=0.9,en-US;q=0.8,en;q=0.7",
  "accept-encoding": "gzip, deflate, br",
  "sec-ch-ua": '"Chromium";v="126", "Google Chrome";v="126", "Not;A=Brand";v="24"',
  "sec-ch-ua-mobile": "?0",
  "sec-ch-ua-platform": '"Windows"',
  "sec-fetch-dest": "document",
  "sec-fetch-mode": "navigate",
  "sec-fetch-site": "none",
  "upgrade-insecure-requests": "1",
};

const cleanUrl = (u) =>
  u ? u.replace(/\\u002F/g, "/").replace(/\\/g, "").replace(/&amp;/g, "&") : null;

const decodeEntities = (s) =>
  s
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&amp;/g, "&");

class Jar {
  constructor() {
    this.map = new Map();
  }
  absorb(setCookie) {
    const lines = Array.isArray(setCookie) ? setCookie : setCookie ? [setCookie] : [];
    for (const line of lines) {
      const pair = String(line).split(";")[0];
      const i = pair.indexOf("=");
      if (i > 0) this.map.set(pair.slice(0, i).trim(), pair.slice(i + 1).trim());
    }
  }
  toString() {
    return [...this.map.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
  }
}

function requestOnce(method, urlStr, jar, headers, body, timeoutMs) {
  return new Promise((resolve, reject) => {
    let target;
    try {
      target = new URL(urlStr);
    } catch {
      reject(new Error(`Invalid URL: ${urlStr}`));
      return;
    }
    const lib = target.protocol === "http:" ? http : https;
    const req = lib.request(
      target,
      {
        method,
        headers: {
          "user-agent": UA,
          ...(jar && jar.toString() ? { cookie: jar.toString() } : {}),
          ...(headers || {}),
        },
      },
      (res) => {
        if (jar) jar.absorb(res.headers["set-cookie"]);
        let stream = res;
        const enc = String(res.headers["content-encoding"] || "").toLowerCase();
        if (enc === "gzip") stream = res.pipe(zlib.createGunzip());
        else if (enc === "deflate") stream = res.pipe(zlib.createInflate());
        else if (enc === "br") stream = res.pipe(zlib.createBrotliDecompress());
        const chunks = [];
        stream.on("data", (c) => chunks.push(c));
        stream.on("end", () =>
          resolve({
            status: res.statusCode || 0,
            headers: res.headers,
            text: Buffer.concat(chunks).toString("utf8"),
          })
        );
        stream.on("error", reject);
        res.on("error", reject);
      }
    );
    req.setTimeout(timeoutMs, () =>
      req.destroy(new Error(`Request timed out after ${timeoutMs}ms: ${urlStr}`))
    );
    req.on("error", reject);
    if (body) req.write(body);
    req.end();
  });
}

async function request(method, url, jar, headers, body, timeoutMs = 25000, redirects = 5) {
  const res = await requestOnce(method, url, jar, headers, body, timeoutMs);
  if (
    method === "GET" &&
    res.status >= 300 &&
    res.status < 400 &&
    res.headers.location &&
    redirects > 0
  ) {
    const next = new URL(res.headers.location, url).toString();
    return request(method, next, jar, headers, body, timeoutMs, redirects - 1);
  }
  return res;
}

async function requestRetry(method, url, jar, headers, body, timeoutMs = 25000) {
  let lastErr = null;
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      return await request(method, url, jar, headers, body, timeoutMs);
    } catch (e) {
      lastErr = e;
      await new Promise((r) => setTimeout(r, 700));
    }
  }
  throw lastErr || new Error(`Request failed: ${url}`);
}

function parseJsonObjectAt(text, start) {
  let depth = 0;
  let inStr = false;
  let esc = false;
  for (let i = start; i < text.length; i++) {
    const c = text[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === "\\") esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') inStr = true;
    else if (c === "{") depth++;
    else if (c === "}") {
      depth--;
      if (depth === 0) {
        try {
          return JSON.parse(text.slice(start, i + 1));
        } catch {
          return null;
        }
      }
    }
  }
  return null;
}

function extractWatchData(html) {
  const marker = 'content="{&quot;meta&quot;';
  const at = html.indexOf(marker);
  if (at >= 0) {
    const from = at + "content=\"".length;
    const end = html.indexOf('"', from);
    if (end > from) {
      try {
        const parsed = JSON.parse(decodeEntities(html.slice(from, end)));
        const data =
          parsed &&
          parsed.data &&
          parsed.data.response &&
          parsed.data.response.$watchV4 &&
          parsed.data.response.$watchV4.data;
        if (data) return data;
      } catch {

      }
    }
  }
  const decoded = decodeEntities(html);
  const keyAt = decoded.indexOf('"accessRightKey"');
  if (keyAt >= 0) {
    const start = decoded.lastIndexOf('{"meta"', keyAt);
    if (start >= 0) {
      const parsed = parseJsonObjectAt(decoded, start);
      const data =
        parsed &&
        parsed.data &&
        parsed.data.response &&
        parsed.data.response.$watchV4 &&
        parsed.data.response.$watchV4.data;
      if (data) return data;
    }
  }
  return null;
}

function parseVideoId(input) {
  const s = String(input || "").trim();
  let m = s.match(/nicovideo\.jp\/watch\/([a-z]{2}\d+|\d{6,})/i);
  if (m) return m[1].toLowerCase();
  m = s.match(/nico\.ms\/([a-z]{2}\d+|\d{6,})/i);
  if (m) return m[1].toLowerCase();
  m = s.match(/nicovideo\.jp\/(?:shorts|thumb_watch)\/([a-z]{2}\d+|\d{6,})/i);
  if (m) return m[1].toLowerCase();
  if (/^(?:sm|nm|so|lv)\d+$/i.test(s) || /^\d{6,}$/.test(s)) return s.toLowerCase();
  return null;
}

function mediaParts(data) {
  const media = data.media || {};
  const domand = media.domand || null;
  const contents = media.contents || {};
  const videos = (domand ? domand.videos : contents.videos) || [];
  const audios = (domand ? domand.audios : contents.audios) || [];
  const accessRightKey =
    (domand && domand.accessRightKey) || media.accessRightKey || null;
  return {
    videos: videos.filter((v) => v && v.isAvailable && v.id),
    audios: audios.filter((a) => a && a.isAvailable && a.id),
    accessRightKey,
  };
}

function qualityLabel(entry, fallbackHeight) {
  if (entry && entry.label) return String(entry.label);
  if (entry && entry.height) return `${entry.height}p`;
  if (fallbackHeight) return `${fallbackHeight}p`;
  return entry && entry.id ? entry.id : "unknown";
}

function parseMasterVariants(text, videos) {
  const byBase = new Map();
  for (const v of videos) byBase.set(v.id, v);
  const lines = String(text || "").split(/\r?\n/);
  const out = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (!line.startsWith("#EXT-X-STREAM-INF")) continue;
    const uri = (lines[i + 1] || "").trim();
    if (!uri) continue;
    const base = uri.split("?")[0].split("/").pop().replace(/\.m3u8$/i, "");
    const entry = byBase.get(base) || null;
    const resM = line.match(/RESOLUTION=(\d+)x(\d+)/);
    const height = resM ? parseInt(resM[2], 10) : entry ? entry.height || null : null;
    out.push({
      quality: entry ? qualityLabel(entry, height) : height ? `${height}p` : base,
      height: height || null,
      url: uri,
    });
  }
  out.sort((a, b) => (b.height || 0) - (a.height || 0));
  const seen = new Set();
  return out.filter((q) => {
    const key = `${q.quality}|${q.url.split("?")[0]}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

async function fetchWatchData(id, jar) {
  const page = await requestRetry(
    "GET",
    `https://www.nicovideo.jp/watch/${id}`,
    jar,
    { ...NAV_HEADERS }
  );
  if (page.status === 404) {
    throw new Error("Video not found — it may be deleted or private");
  }
  if (page.status !== 200) {
    throw new Error(`Watch page returned HTTP ${page.status}`);
  }
  const data = extractWatchData(page.text);
  if (!data || !data.video) {
    throw new Error(
      "Could not extract this video's watch data — it may be deleted, private, or NicoNico changed its page format"
    );
  }
  return data;
}

async function requestAccessRights(id, data, parts, jar) {
  const outputs = [];
  for (const v of parts.videos) {
    for (const a of parts.audios) outputs.push([v.id, a.id]);
  }
  if (!outputs.length) {
    for (const v of parts.videos) outputs.push([v.id]);
  }
  const body = JSON.stringify({ outputs });
  const trackId =
    (data.client && data.client.watchTrackId) ||
    `AAAAAAAAAA_${Date.now()}`;
  const res = await requestRetry(
    "POST",
    `https://nvapi.nicovideo.jp/v1/watch/${encodeURIComponent(id)}/access-rights/hls?actionTrackId=${encodeURIComponent(trackId)}`,
    jar,
    {
      accept: "application/json;charset=utf-8",
      "content-type": "application/json",
      "content-length": Buffer.byteLength(body),
      "x-access-right-key": parts.accessRightKey,
      "x-request-with": "https://www.nicovideo.jp",
      "x-frontend-id": "6",
      "x-frontend-version": "0",
      referer: `https://www.nicovideo.jp/watch/${id}`,
    },
    body
  );
  let json = null;
  try {
    json = JSON.parse(res.text);
  } catch {

  }
  if ((res.status === 200 || res.status === 201) && json && json.data && json.data.contentUrl) {
    return json.data.contentUrl;
  }
  const code = json && json.meta && json.meta.errorCode ? json.meta.errorCode : `HTTP ${res.status}`;
  throw new Error(`NicoNico refused the playback request (${code})`);
}

async function fetchSelf(url) {
  try {
    const id = parseVideoId(url);
    if (!id) throw new Error("Invalid NicoNico URL");

    const jar = new Jar();
    let data = await fetchWatchData(id, jar);
    let parts = mediaParts(data);

    const video = data.video || {};
    if (video.permission && video.permission.isDeleted) {
      throw new Error("This video has been deleted");
    }
    if (video.permission && video.permission.isPrivate) {
      throw new Error("This video is private");
    }
    if (video.permission && video.permission.isAuthenticationRequired) {
      throw new Error("This video requires a NicoNico account to watch");
    }
    if (!parts.videos.length || !parts.accessRightKey) {
      throw new Error(
        "No public playback data for this video — NicoNico may require login for it"
      );
    }

    let masterUrl = null;
    let lastErr = null;
    for (let attempt = 0; attempt < 2 && !masterUrl; attempt++) {
      try {
        masterUrl = await requestAccessRights(id, data, parts, jar);
      } catch (e) {
        lastErr = e;
        if (attempt === 0) {
          data = await fetchWatchData(id, jar);
          parts = mediaParts(data);
          if (!parts.videos.length || !parts.accessRightKey) throw lastErr;
        }
      }
    }
    if (!masterUrl) throw lastErr || new Error("Could not obtain a playback URL");

    let qualities = [];
    try {
      const pl = await requestRetry("GET", masterUrl, jar, {
        accept: "application/vnd.apple.mpegurl, */*",
        referer: "https://www.nicovideo.jp/",
        origin: "https://www.nicovideo.jp",
      });
      if (pl.status === 200) qualities = parseMasterVariants(pl.text, parts.videos);
    } catch {

    }

    const labels = parts.videos.map((v) => qualityLabel(v, v.height || null));
    const bestLabel = labels[0] || null;
    const thumbs = video.thumbnail || {};
    const owner =
      (data.metadata &&
        data.metadata.jsonLd &&
        data.metadata.jsonLd.owner &&
        data.metadata.jsonLd.owner.name) ||
      (data.owner && data.owner.name) ||
      (data.channel && data.channel.name) ||
      null;

    const download = {
      video: cleanUrl(masterUrl),
      url: cleanUrl(masterUrl),
      type: "hls",
      note:
        `Anonymous (not logged in) playback — NicoNico limits guests to ${labels.join(" / ") || "low"} quality; ` +
        "full quality requires a NicoNico account. Signed session HLS URL — download immediately, it expires soon",
    };
    if (bestLabel) download.quality = bestLabel;
    if (qualities.length) {
      download.qualities = qualities.map((q) => ({ quality: q.quality, url: cleanUrl(q.url) }));
    }

    return {
      success: true,
      source: "NicoNico",
      data: {
        title: video.title || "NicoNico Video",
        author: owner,
        duration: typeof video.duration === "number" ? video.duration : null,
        thumbnail: cleanUrl(thumbs.player || thumbs.ogp || thumbs.normal || null),
        download,
      },
    };
  } catch (e) {
    if (/^NicoNico Error:/.test(e.message)) throw e;
    throw new Error("NicoNico Error: " + e.message);
  }
}

module.exports = fetchSelf;
